func:
// Parse incoming raw telemetry values
var raw = msg.payload;
var p1 = raw.pmp001 || {};
var p2 = raw.pmp002 || {};
var raw_tank = raw.tank || {};

// 1. Contextualize Pump 1 (Inlet)
var pmp001_rpm = p1.speed_rpm || 0;
var pmp001_temp = p1.temperature_c || 25.0;
var pmp001_power = p1.power_kw || 0;
var pmp001_current = p1.current_a || 0;
// Simulate anomaly: alert if temperature exceeds 78 degrees Celsius
var anomaly = pmp001_temp > 78.0;

// 2. Contextualize Pump 2 (Outlet)
var pmp002_rpm = p2.speed_rpm || 0;
var pmp002_temp = p2.temperature_c || 25.0;
var pmp002_power = p2.power_kw || 0;
var pmp002_current = p2.current_a || 0;
// Calculate pressure based on active RPM speed
var pmp002_press = (pmp002_rpm / 1500.0) * 8.0;

// 3. Contextualize Tank Level, Pressure, and dynamic flows
var level_liters = raw_tank.level_liters || 500.0;
var level_pct = (level_liters / 1000.0) * 100.0;

// Dynamic P&ID indicators calculations
var pressure_bar = 2.0 + (pmp001_rpm / 1500.0) * 1.5 + (Math.random() - 0.5) * 0.1;
var flow_l_s = 0.0;
if (pmp002_rpm > 0 && raw_tank.v001_open && level_liters > 10) {
    flow_l_s = (pmp002_rpm / 1500.0) * 30.0 + (Math.random() - 0.5) * 0.5;
}

// Format output payload
msg.payload = {
    "pmp001": {
        "speed_rpm": pmp001_rpm,
        "temperature_c": pmp001_temp,
        "power_kw": pmp001_power,
        "current_a": pmp001_current,
        "anomaly_detected": anomaly
    },
    "pmp002": {
        "speed_rpm": pmp002_rpm,
        "temperature_c": pmp002_temp,
        "power_kw": pmp002_power,
        "current_a": pmp002_current,
        "pressure_bar": pmp002_press
    },
    "tank": {
        "level_liters": level_liters,
        "level_pct": level_pct,
        "pressure_bar": pressure_bar,
        "flow_l_s": Math.max(0, flow_l_s)
    }
};

return msg;
